/**
 * Systematics Hero — EMPOWERING THE NEXT
 * Letter-forming dots on canvas (every 2nd SVG circle; logo+line static).
 * Uniform opaque white radius; gentle per-dot oscillation.
 */
(function () {
  'use strict';

  var SVG_URL = 'assets/img/empowering-dot-type.svg';
  var VB_W = 764.53;
  var VB_H = 587.74;
  /** Uniform radius in viewBox units (SVG median ≈ 0.96). */
  var UNIFORM_R = 1.55;
  /** Drift amplitude in viewBox units — stronger visible letter oscillation. */
  var AMP_MIN = 2.5;
  var AMP_MAX = 5;
  var DOT_B64 = '';
  var DOT_COUNT = 9054;

  function HeroParticles(root) {
    this.root = root;
    this.stage = root.querySelector('.sys-hero-stage') || root;
    this.canvas = root.querySelector('[data-hero-particles]') || root.querySelector('canvas');
    this.logo = root.querySelector('[data-hero-logo]');
    this.staticLayer = root.querySelector('[data-hero-static]');
    this.ctx = this.canvas.getContext('2d', { alpha: true });
    this.w = 0;
    this.h = 0;
    this.dpr = 1;
    this.scale = 1;
    this.ox = 0;
    this.oy = 0;
    this.count = 0;
    this.baseX = null;
    this.baseY = null;
    this.phaseX = null;
    this.phaseY = null;
    this.speedX = null;
    this.speedY = null;
    this.ampX = null;
    this.ampY = null;
    this.raf = 0;
    this.t0 = 0;
    this.ready = false;
    this.reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    this._onResize = this.resize.bind(this);
    this._onVis = this.onVisibility.bind(this);
    this.init();
  }

  HeroParticles.prototype.init = function () {
    /* Logo wordmark + line stay visible via [data-hero-static]; do not hide them. */
    if (this.logo && !this.root.querySelector('[data-hero-static]')) {
      this.logo.style.visibility = 'hidden';
      this.logo.setAttribute('aria-hidden', 'true');
    }
    this.resize();
    window.addEventListener('resize', this._onResize, { passive: true });
    document.addEventListener('visibilitychange', this._onVis);
    this.loadDots();
  };

  HeroParticles.prototype.loadDots = function () {
    var self = this;
    function start() {
      self.ready = true;
      self.stage.classList.add('is-ready');
      if (self.reduced) {
        self.drawStatic();
        return;
      }
      self.t0 = performance.now();
      self.loop(self.t0);
    }
    try {
      if (typeof DOT_B64 === 'string' && DOT_B64.length) {
        var bin = atob(DOT_B64);
        var n = DOT_COUNT;
        var baseX = new Float32Array(n);
        var baseY = new Float32Array(n);
        var phaseX = new Float32Array(n);
        var phaseY = new Float32Array(n);
        var speedX = new Float32Array(n);
        var speedY = new Float32Array(n);
        var ampX = new Float32Array(n);
        var ampY = new Float32Array(n);
        // little-endian float32 pairs
        var u8 = new Uint8Array(bin.length);
        for (var i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
        var view = new DataView(u8.buffer);
        for (var i = 0; i < n; i++) {
          baseX[i] = view.getFloat32(i * 8, true);
          baseY[i] = view.getFloat32(i * 8 + 4, true);
          phaseX[i] = Math.random() * Math.PI * 2;
          phaseY[i] = Math.random() * Math.PI * 2;
          speedX[i] = 0.0012 + Math.random() * 0.0015;
          speedY[i] = 0.0011 + Math.random() * 0.0014;
          ampX[i] = AMP_MIN + Math.random() * (AMP_MAX - AMP_MIN);
          ampY[i] = AMP_MIN + Math.random() * (AMP_MAX - AMP_MIN);
        }
        self.count = n;
        self.baseX = baseX;
        self.baseY = baseY;
        self.phaseX = phaseX;
        self.phaseY = phaseY;
        self.speedX = speedX;
        self.speedY = speedY;
        self.ampX = ampX;
        self.ampY = ampY;
        start();
        return;
      }
    } catch (e) {}
    fetch(SVG_URL)
      .then(function (res) {
        if (!res.ok) throw new Error('SVG fetch failed: ' + res.status);
        return res.text();
      })
      .then(function (text) {
        self.parseSvg(text);
        start();
      })
      .catch(function () {
        if (self.logo) self.logo.style.visibility = 'visible';
        self.stage.classList.add('is-ready');
      });
  };


  HeroParticles.prototype.parseSvg = function (text) {
    var re = /<circle[^>]*\bcx="([^"]+)"[^>]*\bcy="([^"]+)"[^>]*\br="([^"]+)"/g;
    var xs = [];
    var ys = [];
    var m;
    while ((m = re.exec(text))) {
      xs.push(+m[1]);
      ys.push(+m[2]);
    }
    var n = xs.length;
    this.count = n;
    this.baseX = new Float32Array(xs);
    this.baseY = new Float32Array(ys);
    this.phaseX = new Float32Array(n);
    this.phaseY = new Float32Array(n);
    this.speedX = new Float32Array(n);
    this.speedY = new Float32Array(n);
    this.ampX = new Float32Array(n);
    this.ampY = new Float32Array(n);
    for (var i = 0; i < n; i++) {
      /* Deterministic-ish phases from index so reload looks stable */
      var h1 = ((i * 2654435761) >>> 0) / 4294967296;
      var h2 = ((i * 2246822519) >>> 0) / 4294967296;
      var h3 = ((i * 3266489917) >>> 0) / 4294967296;
      var h4 = ((i * 668265263) >>> 0) / 4294967296;
      this.phaseX[i] = h1 * Math.PI * 2;
      this.phaseY[i] = h2 * Math.PI * 2;
      this.speedX[i] = 0.0012 + h3 * 0.0015;
      this.speedY[i] = 0.0011 + h4 * 0.0014;
      this.ampX[i] = AMP_MIN + h1 * (AMP_MAX - AMP_MIN);
      this.ampY[i] = AMP_MIN + h2 * (AMP_MAX - AMP_MIN) * 0.85;
    }
  };

  HeroParticles.prototype.resize = function () {
    var rect = this.stage.getBoundingClientRect();
    var w = Math.max(2, Math.floor(rect.width) || this.stage.clientWidth || 320);
    var h = Math.max(2, Math.floor(rect.height) || this.stage.clientHeight || 246);
    var dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.w = w;
    this.h = h;
    this.dpr = dpr;
    this.canvas.width = Math.floor(w * dpr);
    this.canvas.height = Math.floor(h * dpr);
    this.canvas.style.width = w + 'px';
    this.canvas.style.height = h + 'px';
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    /* contain fit of viewBox into stage */
    var sx = w / VB_W;
    var sy = h / VB_H;
    var s = Math.min(sx, sy);
    this.scale = s;
    this.ox = (w - VB_W * s) * 0.5;
    this.oy = (h - VB_H * s) * 0.5;

    if (this.ready && this.reduced) this.drawStatic();
  };

  HeroParticles.prototype.drawStatic = function () {
    var ctx = this.ctx;
    var n = this.count;
    var bx = this.baseX;
    var by = this.baseY;
    var s = this.scale;
    var ox = this.ox;
    var oy = this.oy;
    var r = UNIFORM_R * s;
    ctx.clearRect(0, 0, this.w, this.h);
    ctx.globalAlpha = 1;
    ctx.fillStyle = '#ffffff';
    for (var i = 0; i < n; i++) {
      ctx.beginPath();
      ctx.arc(ox + bx[i] * s, oy + by[i] * s, Math.max(1.15, r), 0, Math.PI * 2);
      ctx.fill();
    }
  };

  HeroParticles.prototype.onVisibility = function () {
    if (document.hidden) {
      if (this.raf) cancelAnimationFrame(this.raf);
      this.raf = 0;
    } else if (!this.reduced && this.ready && !this.raf) {
      this.t0 = performance.now();
      this.loop(this.t0);
    }
  };

  HeroParticles.prototype.loop = function (now) {
    var self = this;
    this.raf = requestAnimationFrame(function (t) { self.loop(t); });
    this.draw(now);
  };

  HeroParticles.prototype.draw = function (now) {
    var t = now - this.t0;
    var ctx = this.ctx;
    var n = this.count;
    var bx = this.baseX;
    var by = this.baseY;
    var px = this.phaseX;
    var py = this.phaseY;
    var sx = this.speedX;
    var sy = this.speedY;
    var ax = this.ampX;
    var ay = this.ampY;
    var scale = this.scale;
    var ox = this.ox;
    var oy = this.oy;
    var r = UNIFORM_R * scale;

    ctx.clearRect(0, 0, this.w, this.h);
    ctx.globalAlpha = 1;
    ctx.fillStyle = '#ffffff';

    for (var i = 0; i < n; i++) {
      var dx = Math.sin(t * sx[i] + px[i]) * ax[i];
      var dy = Math.cos(t * sy[i] + py[i]) * ay[i];
      ctx.beginPath();
      ctx.arc(ox + (bx[i] + dx) * scale, oy + (by[i] + dy) * scale, Math.max(1.15, r), 0, Math.PI * 2);
      ctx.fill();
    }
  };

  function boot() {
    var roots = document.querySelectorAll('[data-sys-hero-particles]');
    for (var i = 0; i < roots.length; i++) new HeroParticles(roots[i]);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();
